import json
import sys
sys.path.insert(0, ".")
from data_core import *
from prisma_numbers import P

ST = json.load(open("stats.json"))
S, YEAR = ST["S"], {int(k): v for k, v in ST["YEAR"].items()}
PROTO = {42, 48}

def tok(ids):
    return "{c:" + ",".join("s%d" % i for i in ids) + "}"

def wd(ids):
    return [i for i in ids if i not in PROTO]

def table_order():
    out = []
    for st in ("S1", "S2", "S3", "S4", "S5", "S6"):
        ids = sorted([n for n in R if R[n][4] == st], key=lambda n: (YEAR[n], n))
        out.extend(ids)
    return out

ORDER = table_order()
BYSTREAM = {st: [n for n in ORDER if R[n][4] == st] for st in STREAMS}
F_IDS = S["flag_members"]["F"]
N_IDS = S["flag_members"]["N"]
I_IDS = S["flag_members"]["I"]
C_IDS = S["flag_members"]["C"]
B_IDS = wd(S["flag_members"]["B"])
M_IDS = wd(S["flag_members"]["M"])
D_IDS = wd(S["flag_members"]["D"])
MEN = S["tumor_members"]["Meningioma"]
GLI = S["tumor_members"]["Glioma"]
MIX = S["tumor_members"]["Mixed"]
cogdir = {k: v for k, v in COG_DIR.items()}
GLI_COG = [n for ids in COG_DIR.values() for n in ids if R[n][3] == "Glioma"]
MEN_COG = [n for ids in COG_DIR.values() for n in ids if R[n][3] == "Meningioma"]
GLI_DECLINE = [n for k in ("Decline (selective or global)", "Transient decline with recovery", "Early decline, single early timepoint", "Selective persistent decline with partial recovery") for n in COG_DIR[k] if R[n][3] == "Glioma"]
assert len(GLI_COG) == 13 and len(MEN_COG) == 4 and len(GLI_DECLINE) == 8
n_bsc = len(wd(COG_CLASS["Brief screener"]))
assert n_bsc == 7

def fmt(n):
    return f"{n:,}"

def results():
    B = []
    A = B.append
    A(("h1", "3. Results"))
    A(("h2", "3.1. Study Selection"))
    A(("p", f"The searches returned {fmt(P['db_total'])} records from four databases and medRxiv and {P['gscholar']} from Google Scholar, a total of {fmt(P['db_total'] + P['gscholar'])} records. Citation searching added {P['citation']} records and the clinical team supplied {P['client']} sources, so {fmt(P['all_records'])} records were identified. After {P['dups']} duplicates were removed from the database and preprint records, {fmt(P['screened'])} records were screened by title and abstract and {fmt(P['ta_excl'])} were excluded. Of {P['sought_db']} reports sought, {P['nr_db']} could not be retrieved and {P['assessed_db']} were assessed in full text. Of these, {P['excl_db']} were excluded (wrong outcome {P['r_outcome_db']}, wrong population {P['r_pop_db']}, wrong publication type {P['r_pub_db']}, wrong study design {P['r_design_db']}, wrong intervention {P['r_int_db']}) and {P['inc_db']} were included. From the other sources, {P['sought_ot']} reports were sought, {P['nr_ot']} were not retrieved, {P['assessed_ot']} were assessed, {P['excl_ot']} were excluded (wrong outcome {P['r_outcome_ot']}, wrong population {P['r_pop_ot']}, wrong study design {P['r_design_ot']}, wrong publication type {P['r_pub_ot']}), and {P['inc_ot']} were included."))
    A(("p", f"In total {P['inc_total']} studies were included. They comprise a core evidence base of {P['core']} studies and an instrument-focused stratum of {P['instr']} studies. The original screening tally was 80 included studies. Ten of these (nine from the databases and one from the other sources) were removed during data charting. One was removed for population (a spinal surgery trial) and nine for outcome, because they reported no perioperative brain injury, cognitive, or clinical outcome (for example an imaging technique comparison, cerebrospinal fluid infection markers, cyst fluid proteomics, tissue receptor characterization, and drug delivery trials). The selection process is shown in Figure 1."))
    A(("figure", "fig1"))
    A(("h2", "3.2. Characteristics of the Core Evidence Base"))
    d = S["design"]
    A(("p", f"The {S['n_total']} core studies were published between {S['year_min']} and {S['year_max']}, and {S['year_2018plus']} appeared from 2018 onward (Figure 2A). They came from {S['n_countries']} countries, most often the United States ({S['country']['USA']}) and China ({S['country']['China']}), followed by the Netherlands ({S['country']['Netherlands']}), Germany ({S['country']['Germany']}), India ({S['country']['India']}), and Italy ({S['country']['Italy']}). One study came from Southeast Asia (Thailand) and none came from Indonesia."))
    A(("p", f"Designs were prospective cohorts ({d['Prospective cohort']}), randomized trials ({d['RCT']}), retrospective cohorts ({d['Retrospective cohort']}), registry cohorts ({d['Registry cohort']}), case-control studies ({d['Case-control']}), case series ({d['Case series']}), mechanistic laboratory studies ({d['Mechanistic laboratory study']}), trial protocols ({d['Trial protocol']}), one cross-sectional study, one non-randomized pilot trial, and one secondary analysis of a trial (Figure 2B). By design, {S['level']['2']} studies ({round(100 * S['level']['2'] / 70)}%) reached level 2, {S['level']['3']} level 3, {S['level']['4']} level 4, and {S['level']['5']} level 5, and two protocols were ungraded. Study samples were glioma only in {S['tumor']['Glioma']} studies, meningioma only in {S['tumor']['Meningioma']}, brain metastasis only in one, and mixed tumor types in {S['tumor']['Mixed']} (Figure 2C). Among the {S['n_with_size']} studies that reported a sample size, the median was {int(S['n_median'])} (interquartile range {int(S['n_q1'])} to {int(S['n_q3'])}, range {S['n_min']} to {fmt(int(S['n_max']))}), and the two protocols planned 90 and 500 participants."))
    A(("p", f"Six evidence streams emerged (Figure 2D, Table 1). Eight studies addressed tumor biology, the microenvironment, and the blood-brain barrier {tok(BYSTREAM['S1'])}. Five addressed systemic frailty indices and perioperative risk {tok(BYSTREAM['S2'])}. Twenty-two followed cognitive trajectories after tumor surgery {tok(BYSTREAM['S3'])}. Six described postoperative delirium or agitation {tok(BYSTREAM['S4'])}. Ten examined perioperative brain injury through imaging, biomarkers, or cerebral physiology {tok(BYSTREAM['S5'])}. Nineteen tested perioperative interventions or reported trial protocols {tok(BYSTREAM['S6'])}. Two studies counted operations and not patients {tok([6, 7])}."))
    A(("figure", "fig2"))
    A(("table", "t1"))
    A(("h2", "3.3. How Frailty Is Defined and Measured (RQ1)"))
    A(("p", f"No core study used the terms brain frailty, cognitive frailty, or tumor-associated frailty in its full text. The label brain frailty in our charting form was a reviewer code applied to studies that used a frailty index, and it does not appear in their own reporting. Frailty was operationalized with general instruments in seven studies. The five-factor modified frailty index (mFI-5) was used in three {tok([16, 25, 58])}, and the eleven-item modified frailty index {tok([5])}, the Hopkins Frailty Score {tok([17])}, the Risk Analysis Index {tok([58])}, the Fried phenotype {tok([67])}, and a comorbidity count used as a proxy {tok([38])} were each used once. Six of the seven studies sampled mixed tumor types and one sampled brain metastases, so no frailty study was restricted to glioma or meningioma. Cut-offs differed even for the same index, since one mFI-5 study grouped patients at 0, 0.2, and above 0.2 {tok([16])} and another at 0, 1, and 2 or more {tok([25])}."))
    A(("p", f"In all seven studies, higher frailty or comorbidity burden was linked to worse outcomes, or a frailty-directed intervention improved them. Postoperative delirium rose from 12.8% in non-frail to 27.0% in pre-frail and 37.5% in frail patients {tok([5])}. In a registry of 20,333 craniotomies, low and medium-to-high mFI-5 raised the odds of 30-day mortality (odds ratios 1.87 and 2.42) {tok([16])}. Frail patients had higher odds of non-home discharge (odds ratio 10.36, 95% confidence interval 3.6 to 30.1) {tok([17])}. Each mFI-5 point added 1.38 hospital days {tok([25])}. The Risk Analysis Index separated 30-day mortality of 1.3% in robust and 12.6% in severely frail patients with brain metastases {tok([58])}. A frailty-originated rehabilitation program lowered delirium from 28.7% to 15.6% {tok([67])}, and delirium was more frequent in patients with three or more comorbidities {tok([38])}. Brain frailty in tumor patients is therefore defined today by borrowing general indices, and the mapped literature offers no brain-specific nomenclature or index."))
    A(("h2", "3.4. Candidate Domains and Instruments (RQ2)"))
    A(("p", f"Table 2 and Figure 3 summarize the four domains. In the systemic domain, the seven studies above supplied the only instruments. In the cognitive domain, {len(wd(C_IDS))} core studies reported cognitive testing and one protocol planned it. Fourteen used multidomain batteries {tok(COG_CLASS['Multidomain battery'])}, four used domain-specific tests {tok(COG_CLASS['Domain-specific tests'])}, and four used computerized batteries {tok(COG_CLASS['Computerized battery'])}. Seven used brief screeners {tok(wd(COG_CLASS['Brief screener']))}, and one relied on a patient-reported scale {tok(COG_CLASS['Patient-reported cognition'])}. The MMSE appeared in five studies {tok([15, 49, 55, 56, 65])} and the MoCA in two studies with data {tok([47, 66])} and one protocol {tok([42])}. Timing ranged from two days before surgery {tok([2])} to a mean of 1.7 years afterward {tok([63])}. One study found that the MMSE-J stayed normal while detailed testing and lesion mapping exposed specific deficits {tok([56])}."))
    A(("p", f"Cognition was impaired before surgery in all {len(BASELINE_COG_IMPAIRED)} studies that compared patients with norms, controls, or cut-offs {tok(BASELINE_COG_IMPAIRED)}. At least one impaired test was found in 73.7% of patients with meningioma in one cohort {tok([24])} and 69% in another {tok([52])}. The postoperative trajectory varied (Table 2). Across the 18 pre-post cohort studies, authors concluded the following. Improvement was reported in {S['cog_dir']['Improved or improved/stable']} {tok(COG_DIR['Improved or improved/stable'])}, no change or a persistent deficit in {S['cog_dir']['No change or persistent deficit']} {tok(COG_DIR['No change or persistent deficit'])}, stability at group level with individual decline in one {tok(COG_DIR['Stable at group level, individual decline'])}, decline in {S['cog_dir']['Decline (selective or global)']} {tok(COG_DIR['Decline (selective or global)'])}, transient decline with recovery in {S['cog_dir']['Transient decline with recovery']} {tok(COG_DIR['Transient decline with recovery'])}, early decline at a single early time point in one {tok(COG_DIR['Early decline, single early timepoint'])}, and selective persistent decline with partial recovery in one {tok(COG_DIR['Selective persistent decline with partial recovery'])}. Tumor type mattered. Of the 13 glioma-only cohorts, 8 reported an early or lasting decline {tok(GLI_DECLINE)} and 2 reported improvement {tok([20, 36])}. Of the four meningioma-only cohorts, three reported improvement {tok([24, 26, 52])} and one reported no change {tok([57])}. Among trials, postoperative MoCA did not differ with magnesium in an underpowered study {tok([47])}, whereas MoCA and the Cognitive Capacity Screening Examination were higher with dexmedetomidine on day 1 {tok([66])}."))
    nd = len(N_IDS)
    A(("p", f"Sixteen core studies assessed neurological or functional outcomes. Eight recorded a binary new deficit on examination {tok(NEURO_TOOLS['Binary new deficit on examination'])}. The others used scales such as the Barthel index {tok(NEURO_TOOLS['Barthel index'])}, the Glasgow Outcome Scale {tok(wd(NEURO_TOOLS['GOS or GOSE']))}, the Karnofsky Performance Status {tok(wd(NEURO_TOOLS['KPS']))}, the modified Rankin Scale {tok(NEURO_TOOLS['mRS'])}, the Glasgow Coma Scale {tok(wd(NEURO_TOOLS['GCS']))}, the NIH Stroke Scale {tok(NEURO_TOOLS['NIHSS'])}, and the House-Brackmann scale {tok(NEURO_TOOLS['House-Brackmann'])}. Intraoperative motor evoked potentials served as a neurological readout in two {tok(NEURO_TOOLS['Intraoperative MEP'])}. This makes nine instruments or definitions, none designed for neuro-oncology, and no core study used the NANO scale. Reported deficit rates differed with definition, from permanent deficits in 6.7% of meningioma operations {tok([6])} and 14% permanent motor deficits in glioma surgery {tok([21])} to early deterioration in 50% of meningioma patients {tok([28])}."))
    A(("p", f"Imaging appeared in {len(I_IDS)} core studies. Six used diffusion-weighted MRI to detect new ischemic lesions {tok(IMG_MODS['Diffusion-weighted MRI for ischemic lesions'])}. Thirteen used volumetric MRI for tumor volume or extent of resection {tok(IMG_MODS['Volumetric MRI for extent of resection or tumor volume'])}, four used perfusion or permeability imaging {tok(IMG_MODS['Perfusion or permeability imaging'])}, seven used functional connectivity with fMRI or magnetoencephalography {tok(IMG_MODS['Functional connectivity (fMRI or MEG)'])}, seven reported CT findings {tok(IMG_MODS['CT-based findings'])}, and one used contrast-enhanced ultrasound {tok(IMG_MODS['Contrast-enhanced ultrasound'])}. Several studies used more than one modality. Imaging mostly described the tumor or documented injury. Two studies used preoperative connectivity to predict cognitive outcome {tok([18, 60])}. No core study derived an imaging frailty score from leukoaraiosis, atrophy, or old vascular lesions, no study measured temporal muscle thickness, and CT served to detect hematoma, edema, pneumocephalus, or midline shift and never to grade frailty {tok([15, 28, 43])}."))
    A(("figure", "fig3"))
    A(("table", "t2"))
    A(("h2", "3.5. Neuroinflammation in Malignant and Benign Tumors (RQ3)"))
    A(("p", f"Direct inflammatory evidence came from glioma and mixed samples (Table 3). In high-grade glioma, CD68-positive macrophages (19% to 27% of cells) outnumbered CD45-positive leukocytes (3% to 7%), and cerebrospinal fluid interleukin-7 was lower than in controls {tok([9])}. In astrocytoma, interleukin-8 and interleukin-6 expression rose with grade and necrosis, and interleukin-8 independently predicted survival {tok([27])}. Peritumoral microdialysis in a mixed sample showed that most cytokines peaked within 8 hours of surgery and fell over 96 hours, with intracerebral levels above serum levels {tok([1])}. A structural barrier defect {tok([29])} and a link between tumor VEGF expression and capillary permeability {tok([33])} supported a vascular route for inflammatory signaling."))
    A(("p", f"The ten meningioma-only studies measured no inflammatory marker. They contributed evidence of barrier-related vulnerability and injury instead. In a sample of 20 gliomas and 7 meningiomas, permeability measured by two MRI methods agreed in gliomas but not meningiomas {tok([13])}. S100B rose after meningioma surgery in two cohorts and tracked bleeding, midline shift, and deterioration {tok([15, 28])}, and 34.9% of meningioma operations produced a new diffusion-weighted lesion {tok([6])}. Cognition was impaired before surgery in four meningioma cohorts {tok([24, 26, 52, 57])}. No core study compared inflammatory markers between meningioma and glioma. The immunological rationale for benign tumors therefore rests on external reviews of macrophage infiltration and its relation to edema {{c:domingues2016,haslund2022}}, and the mapped studies support a shared vulnerability phenotype without testing a shared inflammatory mechanism."))
    A(("p", f"Delirium risk also varied with histology. Five of the six studies that tested tumor type reported higher delirium risk with glioma or malignant tumors {tok(HISTOLOGY_DELIRIUM_POS)}, and one found no association {tok(HISTOLOGY_DELIRIUM_NULL)}. In one cohort, meningioma was protective {tok([31])}. Two trials reported that dexmedetomidine and lidocaine lowered interleukin-6 and tumor necrosis factor alpha at the end of surgery or on day 1 {tok([66, 69])}, and in the dexmedetomidine trial the difference had converged with control by day 3 {tok([66])}."))
    A(("table", "t3"))
    A(("h2", "3.6. Biomarkers of Neuroinflammation and Brain Injury (RQ4)"))
    A(("p", f"Table 4 lists the markers. S100B was the most frequent, with data in 10 studies, followed by neuron-specific enolase (7 studies with data), GFAP (4), tau (1), neurofilament light chain (1), interleukin-6 (5), interleukin-8 (2), tumor necrosis factor alpha (2), and VEGF (3), and one study scored tissue immune cell markers {tok([9])}. Four observational studies followed injury markers after surgery and all four found a postoperative rise {tok([10, 15, 23, 28])}. Three of the four linked the rise to clinical or radiological injury. Plasma GFAP, tau, and neurofilament light chain rose on days 1 and 3, neurofilament light chain showed a second peak at day 10 in keeping with continuing axonal degeneration, and day 1 GFAP and neurofilament light chain were higher in patients with new deficits {tok([10])}. S100B above 0.4 ug/L carried a nine-fold risk of neurologic deterioration {tok([28])}, and its rise correlated with bleeding, midline shift, and MMSE decline {tok([15])}. GFAP rose after glioma surgery but did not track residual tumor, which is consistent with release from tumor cells {tok([23])}."))
    A(("p", f"Eight randomized trials used S100B, neuron-specific enolase, or GFAP as endpoints {tok([39, 50, 51, 53, 61, 64, 66, 69])}. The intervention lowered at least one marker in six trials (electroacupuncture, magnesium in two, goal-directed fluid therapy, dexmedetomidine, and lidocaine) {tok([50, 51, 53, 64, 66, 69])}. The primary S100B endpoint did not differ with magnesium in one trial {tok([39])}, and S100B and neuron-specific enolase were higher with ciprofol than propofol in another {tok([61])}. Sampling was almost always peripheral, from baseline to 24 or 48 hours. Cerebrospinal fluid or microdialysis sampling appeared only in mechanistic studies {tok([1, 9])}, and no perioperative trial measured a cytokine in cerebrospinal fluid. Injury markers therefore indicate that injury occurred, whereas the cytokine evidence needed to show neuroinflammation as such is compartment-specific and sparse."))
    A(("table", "t4"))
    A(("h2", "3.7. Perioperative Brain Injury as a Second Hit (RQ5)"))
    dw = S["dwi"]
    A(("p", f"New diffusion-weighted lesions followed resection in 34.9% of meningioma operations {tok([6])}, 44.2% of glioma operations {tok([7])}, 45.7% of glioma operations with motor monitoring {tok([21])}, and 18.8% of a mixed sample {tok([32])}. In one series, lesions occurred after 31% of operations for newly diagnosed and 80% for recurrent glioma {tok([22])}. The lesions mattered clinically. Among patients with a permanent deficit after meningioma surgery, 72.7% had an infarction {tok([6])}, a new lesion was the only multivariable predictor of incomplete recovery at day 7 and day 30 {tok([32])}, and deficits were more frequent with lesions {tok([22])}. Table 5 summarizes this and the other second-hit evidence."))
    A(("p", f"Delirium and agitation occurred in 4.2% to 35% of patients in observational cohorts and in 28.7% to 46% of control arms, depending on instrument and definition {tok([5, 31, 38, 40, 43, 62, 65, 49, 67])}. Later postoperative delirium occurred in 58.8% of patients with emergence delirium and in 4.7% of those without {tok([40])}. Hemodynamic findings were mixed. Impaired autoregulation before surgery persisted after resection in all affected patients {tok([8])}, intraoperative mean arterial pressure below 65 mmHg was not associated with delirium {tok([65])}, and a lower stroke volume variation threshold was linked to fewer new neurologic events (17.5% against 40%) {tok([64])}. Dexmedetomidine lowered delirium from 46% to 22% {tok([49])}."))
    A(("p", f"Preoperative state predicted postoperative outcome in several designs. Presurgical cognition was the strongest predictor of early postsurgical cognition {tok([34])}, frailty strata predicted delirium {tok([5])}, raised intracranial pressure was linked to impairment before surgery {tok([24])}, and presurgical connectivity predicted later working memory {tok([60])}. Four trials tested magnesium as a protective agent {tok([39, 47, 51, 53])}. Two found lower S100B {tok([51, 53])}, one found no primary difference but smaller cavities and less gliosis at six months in the tumor subgroup {tok([39])}, and one found no difference in MoCA {tok([47])}. No core study examined the interaction between a preoperative vulnerability measure and a postoperative injury marker in the same patients."))
    A(("table", "t5"))
    A(("h2", "3.8. Instrument-Focused Stratum (RQ6)"))
    A(("p", "None of the 70 core studies used MoCA-INA or NANO-Ina, and none evaluated these instruments before and after surgery. The instrument-focused stratum (Table 6) added six studies. The NANO scale covers nine neurologic domains, showed more than 90% inter-observer agreement (kappa 0.35 to 0.83), and took a median of 4 minutes to administer {c:nayak2017}. Its Indonesian version was tested in 30 patients with brain tumors by two physicians and reached kappa values from 0.629 for sensation to 0.935 for facial strength. Most patients (77%) were untreated, and the work came from a single center {c:angelita2026}."))
    A(("p", "For cognition, a feasibility study in 71 patients with primary central nervous system tumors found a median MoCA of 27, with 32% abnormal at a cut-off of 25 or lower. Lower scores accompanied lower Karnofsky status, older age, and greater self-reported cognitive symptom burden {c:jammula2022}. In 33 Indonesian patients with brain tumors assessed at diagnosis, mean scores were 21.79 on the MoCA-Ina and 23.76 on the MMSE. Impairment clustered at 7 to 9 years of education. Attention and calculation were impaired in 90.9% on the MMSE, and delayed recall was impaired in 90.9% on the MoCA-Ina {c:bangun2018}. In 83 older adults without a tumor, MoCA-INA scores averaged 21.06 against 24.96 for the MMSE (correlation 0.71) {c:rambe2017}. In 31 anesthesiology residents, mean MoCA-INA fell from 26.84 to 25.00 after a 24-hour on-call period {c:wonggo2025}. The Indonesian scoring sheet sets a maximum of 30, treats 26 or more as normal, and adds one point for 12 or fewer years of formal education when the total is below 30. Together these studies show that both instruments can be administered in Indonesian clinical settings, that NANO-Ina agrees well between raters, and that MoCA-INA detects impairment and short-term change. None of them tested responsiveness to craniotomy."))
    A(("table", "t6"))
    A(("h2", "3.9. Integrated Evidence Map and Conceptual Synthesis"))
    A(("p", "Figure 4 places each domain against tumor category and shades each cell by the share of graded studies at level 2. Cognitive testing and imaging carried the most evidence and were concentrated in glioma and meningioma cohorts. Systemic frailty indices, delirium, and hemodynamic studies came almost entirely from mixed samples. Inflammatory and tumor-tissue markers and tumor biology came from glioma and mixed samples, and none came from meningioma-only samples. Among the mechanistic domains, only brain injury biomarkers (three studies {c:s15,s28,s61}) and hemodynamics (one study {c:s61}) had data in meningioma-only samples."))
    A(("p", "The synthesis supports a four-domain construct with a two-hit course (Figure 5). The tumor produces mass effect, edema, barrier disruption, and local inflammation, and these are visible in the mapped evidence as impaired cognition, frailty-linked risk, and preoperative neurological and imaging abnormalities. Surgery and anesthesia then add ischemic injury, marker release, and delirium. The mapped studies describe each hit and show that preoperative state predicts postoperative course, but none tested the interaction."))
    A(("figure", "fig4"))
    A(("figure", "fig5"))
    return B
